--[[
    VeevHUD - French (frFR) Localization

    AI-GENERATED translation (by Claude) -- NOT yet reviewed by a native speaker.

    >> Contributions welcome! << Spotted an awkward or wrong string? Edit its
    L["..."] = "..." value below and open a pull request (or an issue) at
    https://github.com/veev-code/VeevHUD  -- native speakers especially appreciated.
    Any key omitted here falls back to English automatically (see enUS.lua).
]]

local L = LibStub("AceLocale-3.0"):NewLocale("VeevHUD", "frFR")
if not L then return end

L["Outline"] = "Contour"
L["Shadow"] = "Ombre"
L["Both"] = "Les deux"
L["None"] = "Aucun"
L["Inherit (Global)"] = "Hériter (global)"
L["Off"] = "Désactivé"
L["Primary Row"] = "Rangée principale"
L["Primary + Secondary Rows"] = "Rangées principale + secondaire"
L["Secondary + Utility Rows"] = "Rangées secondaire + utilitaire"
L["Utility Row"] = "Rangée utilitaire"
L["All Rows"] = "Toutes les rangées"
L["Prediction"] = "Prédiction"
L["Fill"] = "Remplissage"
L["Bar"] = "Barre"
L["Spark"] = "Étincelle"
L["Current"] = "Actuel"
L["%"] = "%"
L["Current (%)"] = "Actuel (%)"
L["Current / Max"] = "Actuel / Max"
L["Current / Max (%)"] = "Actuel / Max (%)"
L["Deficit"] = "Déficit"
L["Abbreviated (4.5k)"] = "Abrégé (4.5k)"
L["Full (4523)"] = "Complet (4523)"
L["Comma (4,523)"] = "Virgule (4,523)"
L["Default: "] = "Par défaut : "
L["Core rotation abilities used every fight — your most important cooldowns."] = "Capacités de rotation principale utilisées à chaque combat — vos temps de recharge les plus importants."
L["Throughput cooldowns, maintenance buffs, and situational damage or healing abilities."] = "Temps de recharge de puissance, améliorations à maintenir, et capacités de dégâts ou de soins situationnelles."
L["Crowd control, interrupts, defensives, and movement abilities."] = "Contrôle de foule, interruptions, défensives et capacités de déplacement."
L["Totems, trinkets, and other supplementary icons."] = "Totems, bijoux et autres icônes supplémentaires."
L["Enabled"] = "Activé"
L["Enables or disables this row. When disabled, abilities assigned to this row are hidden and the row takes no space on the HUD."] = "Active ou désactive cette rangée. Lorsqu'elle est désactivée, les capacités assignées à cette rangée sont masquées et la rangée n'occupe aucun espace sur l'ATH."
L["Size"] = "Taille"
L["Icon Size"] = "Taille des icônes"
L["The size of each ability icon in this row, in pixels. Each row can have different-sized icons — for example, larger icons for your main rotation and smaller ones for utility."] = "La taille de chaque icône de capacité dans cette rangée, en pixels. Chaque rangée peut avoir des icônes de tailles différentes — par exemple, des icônes plus grandes pour votre rotation principale et plus petites pour l'utilitaire."
L["Max Icons"] = "Icônes max"
L["The maximum number of ability icons that can appear in this row. If you assign more spells than this limit, the extra ones won't be shown."] = "Le nombre maximal d'icônes de capacités pouvant apparaître dans cette rangée. Si vous assignez plus de sorts que cette limite, les sorts supplémentaires ne seront pas affichés."
L["Aspect Ratio"] = "Rapport d'aspect"
L["Override the icon shape for this row. |cffffffffInherit|r uses the global setting from Appearance."] = "Remplace la forme des icônes pour cette rangée. |cffffffffHériter|r utilise le réglage global de l'Apparence."
L["Inherit"] = "Hériter"
L["Square (1:1)"] = "Carré (1:1)"
L["Slightly Compact"] = "Légèrement compact"
L["Compact (4:3)"] = "Compact (4:3)"
L["Very Compact"] = "Très compact"
L["Ultra Compact (2:1)"] = "Ultra compact (2:1)"
L["Flow Layout"] = "Disposition fluide"
L["Wraps icons into multiple lines instead of displaying them all in a single long line. The Icons Per Row setting controls the maximum icons per line.\n\nTo avoid a sparse last row, icons are moved down from the previous row — for example, 8 icons at 6 per row becomes 5 and 3 instead of 6 and 2."] = "Répartit les icônes sur plusieurs lignes au lieu de les afficher toutes sur une seule longue ligne. Le réglage Icônes par rangée contrôle le nombre maximal d'icônes par ligne.\n\nPour éviter une dernière rangée trop clairsemée, des icônes sont déplacées vers le bas depuis la rangée précédente — par exemple, 8 icônes à 6 par rangée deviennent 5 et 3 au lieu de 6 et 2."
L["Icons Per Row"] = "Icônes par rangée"
L["The maximum number of icons on each line before wrapping to the next. Rows fill from the top, so earlier rows are always full.\n\nTo avoid a sparse last row, icons are moved down from the previous row — for example, 14 icons at 6 per row becomes 6, 5, 3 instead of 6, 6, 2."] = "Le nombre maximal d'icônes sur chaque ligne avant de passer à la suivante. Les rangées se remplissent depuis le haut, donc les premières rangées sont toujours pleines.\n\nPour éviter une dernière rangée trop clairsemée, des icônes sont déplacées vers le bas depuis la rangée précédente — par exemple, 14 icônes à 6 par rangée deviennent 6, 5, 3 au lieu de 6, 6, 2."
L["Reorder the vertical layout of the HUD and adjust spacing between elements."] = "Réorganisez la disposition verticale de l'ATH et ajustez l'espacement entre les éléments."
L["Up"] = "Haut"
L["Down"] = "Bas"
L["Gap above %s"] = "Espace au-dessus de %s"
L["Pixels of space between %s and %s."] = "Pixels d'espace entre %s et %s."
L["VeevHUD"] = "VeevHUD"
L["Version "] = "Version "
L["General"] = "Général"
L["Global settings that affect the entire HUD. Individual modules have their own tabs."] = "Réglages globaux affectant l'ensemble de l'ATH. Les modules individuels possèdent leurs propres onglets."
L["Position and Scale"] = "Position et échelle"
L["Horizontal Offset"] = "Décalage horizontal"
L["Moves the entire HUD left or right from the center of the screen. Negative values shift it left, positive values shift it right. The range adjusts to your screen resolution."] = "Déplace l'ensemble de l'ATH vers la gauche ou la droite à partir du centre de l'écran. Les valeurs négatives le décalent vers la gauche, les valeurs positives vers la droite. La plage s'ajuste à la résolution de votre écran."
L["Vertical Offset"] = "Décalage vertical"
L["Moves the entire HUD up or down on your screen. Negative values move it below center, positive values move it above. The range adjusts to your screen resolution."] = "Déplace l'ensemble de l'ATH vers le haut ou le bas sur votre écran. Les valeurs négatives le placent sous le centre, les valeurs positives au-dessus. La plage s'ajuste à la résolution de votre écran."
L["Scale"] = "Échelle"
L["Makes everything in the HUD bigger or smaller. 100% is the normal size. Increase if you have trouble seeing the icons, decrease if they take up too much screen space."] = "Agrandit ou réduit tout dans l'ATH. 100 % correspond à la taille normale. Augmentez si vous avez du mal à voir les icônes, réduisez si elles occupent trop d'espace à l'écran."
L["Appearance"] = "Apparence"
L["Font"] = "Police"
L["The font used for all text in the HUD, including cooldown timers, stack counts, health/resource values, and proc durations.\n\nIf you have font-sharing addons installed (SharedMedia, etc.), their fonts will appear here automatically."] = "La police utilisée pour tout le texte de l'ATH, y compris les minuteurs de temps de recharge, le nombre de cumuls, les valeurs de vie/ressource et les durées de proc.\n\nSi vous avez des addons de partage de polices installés (SharedMedia, etc.), leurs polices apparaîtront ici automatiquement."
L["Text Color"] = "Couleur du texte"
L["The color used for cooldown countdowns, duration timers, and stack counts across all HUD elements."] = "La couleur utilisée pour les décomptes de temps de recharge, les minuteurs de durée et le nombre de cumuls sur tous les éléments de l'ATH."
L["Text Outline"] = "Contour du texte"
L["Controls how text is rendered across all HUD elements.\n\n|cffffffffOutline|r — Font outline only.\n|cffffffffShadow|r — Drop shadow only (cleaner at small sizes).\n|cffffffffBoth|r — Font outline + drop shadow (maximum readability).\n|cffffffffNone|r — No outline or shadow.\n\nIndividual elements can override this in their own settings."] = "Contrôle le rendu du texte sur tous les éléments de l'ATH.\n\n|cffffffffContour|r — Contour de police uniquement.\n|cffffffffOmbre|r — Ombre portée uniquement (plus net en petite taille).\n|cffffffffLes deux|r — Contour de police + ombre portée (lisibilité maximale).\n|cffffffffAucun|r — Aucun contour ni ombre.\n\nLes éléments individuels peuvent remplacer ce réglage dans leurs propres paramètres."
L["Bar Texture"] = "Texture des barres"
L["The texture used for all status bars in the HUD, including health, resource, combo point, and energy ticker bars.\n\nIf you have texture-sharing addons installed (SharedMedia, etc.), their textures will appear here automatically."] = "La texture utilisée pour toutes les barres d'état de l'ATH, y compris les barres de vie, de ressource, de points de combo et de tic d'énergie.\n\nSi vous avez des addons de partage de textures installés (SharedMedia, etc.), leurs textures apparaîtront ici automatiquement."
L["Bar Gradient"] = "Dégradé des barres"
L["Adds a subtle dark-to-light gradient across all status bars (health, resource, combo points, and energy ticker), giving them more visual depth instead of a flat solid color."] = "Ajoute un léger dégradé du foncé au clair sur toutes les barres d'état (vie, ressource, points de combo et tic d'énergie), leur donnant plus de profondeur visuelle au lieu d'une couleur unie et plate."
L["Icon Zoom"] = "Zoom des icônes"
L["Zooms into each icon's artwork, cropping the edges. Affects ability rows and Aura Tracker. Useful for removing the default border that some spell textures have. 0% shows the full icon, 16% is a subtle crop."] = "Zoome sur le visuel de chaque icône en rognant les bords. Affecte les rangées de capacités et le Suivi d'auras. Utile pour supprimer la bordure par défaut de certaines textures de sorts. 0 % affiche l'icône complète, 16 % est un rognage subtil."
L["Sound"] = "Son"
L["Sound Channel"] = "Canal sonore"
L["Audio channel for all VeevHUD sound alerts.\n\n|cffffffffMaster|r — Always plays regardless of volume sliders.\n|cffffffffSound Effects|r — Respects the Sound Effects volume slider.\n|cffffffffMusic|r — Respects the Music volume slider.\n|cffffffffAmbience|r — Respects the Ambience volume slider."] = "Canal audio pour toutes les alertes sonores de VeevHUD.\n\n|cffffffffPrincipal|r — Joue toujours, quels que soient les curseurs de volume.\n|cffffffffEffets sonores|r — Respecte le curseur de volume des effets sonores.\n|cffffffffMusique|r — Respecte le curseur de volume de la musique.\n|cffffffffAmbiance|r — Respecte le curseur de volume de l'ambiance."
L["Register Sound Kit ID"] = "Enregistrer un ID de kit sonore"
L["Enter a WoW Sound Kit ID (a number) to register it as an available sound. Once registered, it appears in all sound dropdowns.\n\nBrowse IDs at: wowhead.com/sounds\n\nExamples: 8959 (raid warning), 11466 (Illidan), 8174 (PvP flag).\n\nNote: the speaker preview button in dropdowns does not work for Kit IDs, but the sound plays correctly in-game."] = "Saisissez un ID de kit sonore WoW (un nombre) pour l'enregistrer comme son disponible. Une fois enregistré, il apparaît dans tous les menus déroulants de sons.\n\nParcourez les ID sur : wowhead.com/sounds\n\nExemples : 8959 (alerte de raid), 11466 (Illidan), 8174 (drapeau JcJ).\n\nNote : le bouton d'aperçu (haut-parleur) des menus déroulants ne fonctionne pas pour les ID de kit, mais le son est joué correctement en jeu."
L["Invalid Sound Kit ID: %s"] = "ID de kit sonore invalide : %s"
L["Playing Kit ID %s — registered as %s (top of sound dropdowns)."] = "Lecture de l'ID de kit %s — enregistré sous %s (en haut des menus déroulants de sons)."
L["Sound Kit ID registration failed — LibSharedMedia not available."] = "Échec de l'enregistrement de l'ID de kit sonore — LibSharedMedia non disponible."
L["Visibility"] = "Visibilité"
L["Out of Combat Opacity"] = "Opacité hors combat"
L["Controls the HUD's visibility when not in combat. Use this to fade the HUD when out of combat so it's less distracting. 100% = fully visible, 50% = half transparent, 0% = invisible.\n\nNote: This setting is ignored while the config panel is open so you can see the HUD while configuring."] = "Contrôle la visibilité de l'ATH hors combat. Utilisez ce réglage pour estomper l'ATH hors combat afin qu'il distraie moins. 100 % = entièrement visible, 50 % = à moitié transparent, 0 % = invisible.\n\nNote : ce réglage est ignoré tant que le panneau de configuration est ouvert, afin que vous puissiez voir l'ATH pendant la configuration."
L["Hide on Flight Path"] = "Masquer sur un trajet aérien"
L["Automatically hides the HUD when you're on a flight path (taxi). The HUD will reappear when you land. Useful to keep your screen clean while traveling.\n\nNote: This setting is ignored while the config panel is open so you can see the HUD while configuring."] = "Masque automatiquement l'ATH lorsque vous êtes sur un trajet aérien (taxi). L'ATH réapparaît à l'atterrissage. Utile pour garder votre écran dégagé pendant les déplacements.\n\nNote : ce réglage est ignoré tant que le panneau de configuration est ouvert, afin que vous puissiez voir l'ATH pendant la configuration."
L["Animations"] = "Animations"
L["Smooth Bar Animation"] = "Animation fluide des barres"
L["Health bars, resource bars, and the resource-cost overlay on ability icons animate smoothly instead of jumping when values change."] = "Les barres de vie, les barres de ressource et la surimpression du coût en ressource sur les icônes de capacités s'animent en douceur au lieu de sauter lorsque les valeurs changent."
L["Smooth Dim Transition"] = "Transition d'atténuation fluide"
L["When icons fade in or out (e.g., dimming on cooldown), the transition is gradual instead of instant. Disable for snappier visual feedback."] = "Lorsque les icônes apparaissent ou disparaissent en fondu (p. ex. atténuation en temps de recharge), la transition est progressive au lieu d'être instantanée. Désactivez pour un retour visuel plus réactif."
L["Ability Rows"] = "Rangées de capacités"
L["Default visual settings for all ability rows. Individual rows can override icon shape in their own tabs."] = "Réglages visuels par défaut pour toutes les rangées de capacités. Les rangées individuelles peuvent remplacer la forme des icônes dans leurs propres onglets."
L["Tip: Install the Masque addon to reskin ability icons with custom button styles."] = "Astuce : installez l'addon Masque pour relooker les icônes de capacités avec des styles de boutons personnalisés."
L["Shape"] = "Forme"
L["Default icon shape for all ability rows. Individual rows can override this in their own settings. Aura Tracker has its own setting under Bars."] = "Forme d'icône par défaut pour toutes les rangées de capacités. Les rangées individuelles peuvent remplacer ce réglage dans leurs propres paramètres. Le Suivi d'auras possède son propre réglage sous Barres."
L["Spacing"] = "Espacement"
L["Icon Spacing"] = "Espacement des icônes"
L["The horizontal gap in pixels between each ability icon within a row. A small gap (2-4) helps visually separate icons. Set to 0 for icons to touch. Negative values allow overlap, which may look better with certain skins."] = "L'écart horizontal en pixels entre chaque icône de capacité au sein d'une rangée. Un petit écart (2-4) aide à séparer visuellement les icônes. Réglez sur 0 pour que les icônes se touchent. Les valeurs négatives autorisent le chevauchement, ce qui peut mieux rendre avec certains skins."
L["Flow Row Spacing"] = "Espacement des rangées fluides"
L["When a row uses flow layout and icons overflow to a second line, this is the vertical gap between lines."] = "Lorsqu'une rangée utilise la disposition fluide et que les icônes débordent sur une deuxième ligne, ceci est l'écart vertical entre les lignes."
L["Opacity"] = "Opacité"
L["Ready Opacity"] = "Opacité (prêt)"
L["How visible icons are when the ability is ready to use. 100% means fully visible, lower values make ready abilities slightly transparent. Most people want this at 100%."] = "Le niveau de visibilité des icônes lorsque la capacité est prête à être utilisée. 100 % signifie entièrement visible, les valeurs plus faibles rendent les capacités prêtes légèrement transparentes. La plupart des gens préfèrent 100 %."
L["Cooldown Opacity"] = "Opacité (temps de recharge)"
L["How visible icons are when on cooldown (for rows with Dim On Cooldown enabled). A lower value (like 30%) makes cooldown abilities fade out so you can focus on what's ready. Higher values keep them visible."] = "Le niveau de visibilité des icônes en temps de recharge (pour les rangées avec Atténuer en temps de recharge activé). Une valeur plus faible (comme 30 %) estompe les capacités en recharge afin que vous puissiez vous concentrer sur ce qui est prêt. Les valeurs plus élevées les gardent visibles."
L["Grey Out Unusable"] = "Griser les capacités inutilisables"
L["Makes icons grey when you don't have enough mana, rage, or energy to use the ability, or when you're in the wrong stance. Works the same way as WoW's default action bars.\n\nAutomatically disabled while resting in an inn or city to avoid constant grey-outs on combat abilities."] = "Grise les icônes lorsque vous n'avez pas assez de mana, de rage ou d'énergie pour utiliser la capacité, ou lorsque vous êtes dans la mauvaise posture. Fonctionne de la même manière que les barres d'action par défaut de WoW.\n\nAutomatiquement désactivé lorsque vous vous reposez dans une auberge ou une ville, afin d'éviter le grisage constant des capacités de combat."
L["Cooldowns"] = "Temps de recharge"
L["How cooldown information is displayed on ability icons."] = "Comment les informations de temps de recharge sont affichées sur les icônes de capacités."
L["Display"] = "Affichage"
L["Cooldown Text"] = "Texte du temps de recharge"
L["Displays the remaining cooldown time as numbers on top of each icon. When enabled, VeevHUD shows its own text and hides text from addons like OmniCC. Select which rows display cooldown text."] = "Affiche le temps de recharge restant sous forme de chiffres sur chaque icône. Lorsqu'il est activé, VeevHUD affiche son propre texte et masque celui des addons comme OmniCC. Sélectionnez les rangées qui affichent le texte du temps de recharge."
L["Text outline style for ability icon text (cooldowns, stacks, charges, keybinds)."] = "Style de contour du texte des icônes de capacités (temps de recharge, cumuls, charges, raccourcis)."
L["Minutes Threshold"] = "Seuil de minutes"
L["Remaining times above this many minutes are shown compactly. At the default of 2, 3 minutes 27 seconds is shown as 3m, while 1 minute 45 seconds is shown as 1:45."] = "Les temps restants au-dessus de ce nombre de minutes sont affichés de façon compacte. À la valeur par défaut de 2, 3 minutes 27 secondes s'affiche sous la forme 3m, tandis que 1 minute 45 secondes s'affiche sous la forme 1:45."
L["Decimal Threshold"] = "Seuil décimal"
L["Remaining times below this many seconds are shown with one decimal. At the default of 2, 3.4 seconds is shown as 3, while 1.8 seconds is shown as 1.8."] = "Les temps restants en dessous de ce nombre de secondes sont affichés avec une décimale. À la valeur par défaut de 2, 3,4 secondes s'affiche sous la forme 3, tandis que 1,8 seconde s'affiche sous la forme 1.8."
L["Cooldown Spiral"] = "Spirale de temps de recharge"
L["Shows the dark 'clock sweep' overlay on abilities that are on cooldown. This visual helps you see at a glance how much time remains. Select which rows display the cooldown spiral."] = "Affiche la surimpression sombre de « balayage d'horloge » sur les capacités en temps de recharge. Ce visuel vous aide à voir d'un coup d'œil le temps restant. Sélectionnez les rangées qui affichent la spirale de temps de recharge."
L["Show GCD"] = "Afficher le TdRG"
L["Controls which rows display the Global Cooldown (GCD) spinner. The GCD is the brief ~1.5 second lockout after using most abilities. Showing GCD helps you see when you can press your next ability."] = "Contrôle les rangées qui affichent l'indicateur du temps de recharge global (TdRG). Le TdRG est le bref verrouillage d'environ 1,5 seconde après l'utilisation de la plupart des capacités. Afficher le TdRG vous aide à voir quand vous pouvez lancer votre prochaine capacité."
L["Behavior"] = "Comportement"
L["Dim On Cooldown"] = "Atténuer en temps de recharge"
L["Controls which rows fade out (become transparent) when abilities are on cooldown. The amount they fade is controlled by the |cffffffffCooldown Opacity|r setting.\n\nRows without dimming stay at full brightness and use greying-out to indicate unavailability instead. Many players keep the Primary row undimmed so their core rotation stays visually prominent."] = "Contrôle les rangées qui s'estompent (deviennent transparentes) lorsque les capacités sont en temps de recharge. Le degré d'atténuation est contrôlé par le réglage |cffffffffOpacité (temps de recharge)|r.\n\nLes rangées sans atténuation restent à pleine luminosité et utilisent plutôt le grisage pour indiquer l'indisponibilité. De nombreux joueurs gardent la rangée principale non atténuée afin que leur rotation principale reste visuellement bien visible."
L["Cooldown Sparkle"] = "Scintillement de fin de recharge"
L["Plays WoW's native sparkle animation when a cooldown finishes. Also triggers after the GCD, matching default action bar behavior. This is purely cooldown-based — it does not check resources or other usability conditions."] = "Joue l'animation de scintillement native de WoW lorsqu'un temps de recharge se termine. Se déclenche aussi après le TdRG, conformément au comportement par défaut des barres d'action. Cela repose purement sur le temps de recharge — cela ne vérifie pas les ressources ni d'autres conditions d'utilisation."
L["Cooldown Spiral Opacity"] = "Opacité de la spirale de temps de recharge"
L["How dark the spiral overlay appears during ability cooldowns. Lower values make it more subtle and transparent.\n\nNote: Even at 100%, the spiral won't completely obscure the icon — WoW's cooldown texture has built-in transparency."] = "Le niveau d'obscurité de la spirale pendant les temps de recharge des capacités. Les valeurs plus faibles la rendent plus subtile et transparente.\n\nNote : même à 100 %, la spirale ne masquera pas complètement l'icône — la texture de temps de recharge de WoW possède une transparence intégrée."
L["Resources"] = "Ressources"
L["How resource costs (mana, rage, energy) are shown on ability icons."] = "Comment les coûts en ressource (mana, rage, énergie) sont affichés sur les icônes de capacités."
L["Display Mode"] = "Mode d'affichage"
L["How ability icons show whether you can afford to cast them:\n\n|cffffffffPrediction|r — Extends the cooldown sweep to include resource regeneration time. The icon shows how long until you can actually cast, accounting for both cooldown and resource cost. Energy and Mana predictions are tick-aware and very accurate. Rage falls back to Fill since rage income is unpredictable.\n\n|cffffffffFill|r — Darkens the icon from top to bottom proportional to missing resources. Simple and easy to read.\n\n|cffffffffBar|r — Shows a small colored bar at the bottom of each icon that fills up as you gain resources."] = "Comment les icônes de capacités indiquent si vous pouvez vous permettre de les lancer :\n\n|cffffffffPrédiction|r — Prolonge le balayage de temps de recharge pour inclure le temps de régénération de la ressource. L'icône indique le délai avant que vous puissiez réellement lancer le sort, en tenant compte à la fois du temps de recharge et du coût en ressource. Les prédictions d'énergie et de mana tiennent compte des tics et sont très précises. La rage se rabat sur le Remplissage, car les gains de rage sont imprévisibles.\n\n|cffffffffRemplissage|r — Assombrit l'icône de haut en bas proportionnellement aux ressources manquantes. Simple et facile à lire.\n\n|cffffffffBarre|r — Affiche une petite barre colorée en bas de chaque icône qui se remplit à mesure que vous gagnez des ressources."
L["Show On Rows"] = "Afficher sur les rangées"
L["Choose which rows show resource cost information on their icons. When enabled, you can see at a glance whether you have enough mana, rage, or energy to cast each ability."] = "Choisissez les rangées qui affichent les informations de coût en ressource sur leurs icônes. Lorsqu'il est activé, vous pouvez voir d'un coup d'œil si vous avez assez de mana, de rage ou d'énergie pour lancer chaque capacité."
L["Show During Cooldowns"] = "Afficher pendant les temps de recharge"
L["Shows the resource cost overlay on icons while they are on cooldown, so you can see your resource state through the cooldown spiral. When disabled, the resource overlay only appears when the ability is off cooldown."] = "Affiche la surimpression du coût en ressource sur les icônes pendant qu'elles sont en temps de recharge, afin que vous puissiez voir l'état de votre ressource à travers la spirale de temps de recharge. Lorsqu'il est désactivé, la surimpression de ressource n'apparaît que lorsque la capacité n'est plus en recharge."
L["Fill Style"] = "Style de remplissage"
L["Use Resource Color"] = "Utiliser la couleur de ressource"
L["Uses your resource type color for the fill overlay — red for rage, blue for mana, yellow for energy — instead of the custom Fill Color."] = "Utilise la couleur de votre type de ressource pour la surimpression de remplissage — rouge pour la rage, bleu pour le mana, jaune pour l'énergie — au lieu de la Couleur de remplissage personnalisée."
L["Fill Color"] = "Couleur de remplissage"
L["The color of the resource cost fill overlay on icons. Default is black (a dark overlay showing missing resources). Only used when Use Resource Color is unchecked."] = "La couleur de la surimpression de remplissage du coût en ressource sur les icônes. Par défaut, noir (une surimpression sombre indiquant les ressources manquantes). Utilisée uniquement lorsque Utiliser la couleur de ressource est décoché."
L["Fill Opacity"] = "Opacité de remplissage"
L["How opaque the resource cost overlay appears on icons. Higher values make it more obvious when you can't afford an ability. Applies to Fill mode and Prediction mode's fill fallback (used for rage and when predictions are unavailable)."] = "Le niveau d'opacité de la surimpression du coût en ressource sur les icônes. Les valeurs plus élevées la rendent plus évidente lorsque vous ne pouvez pas vous permettre une capacité. S'applique au mode Remplissage et au repli de remplissage du mode Prédiction (utilisé pour la rage et lorsque les prédictions ne sont pas disponibles)."
L["Invert Fill"] = "Inverser le remplissage"
L["Inverts the fill direction. Normal: overlay covers from top down showing missing resources. Inverted: overlay fills from bottom up showing current resources."] = "Inverse le sens du remplissage. Normal : la surimpression couvre de haut en bas, indiquant les ressources manquantes. Inversé : la surimpression se remplit de bas en haut, indiquant les ressources actuelles."
L["Bar Style"] = "Style de barre"
L["Uses your resource type color for the bar — red for rage, blue for mana, yellow for energy — instead of the custom Bar Color."] = "Utilise la couleur de votre type de ressource pour la barre — rouge pour la rage, bleu pour le mana, jaune pour l'énergie — au lieu de la Couleur de barre personnalisée."
L["Bar Color"] = "Couleur de barre"
L["The color of the resource bar at the bottom of icons. Only used when Use Resource Color is unchecked."] = "La couleur de la barre de ressource en bas des icônes. Utilisée uniquement lorsque Utiliser la couleur de ressource est décoché."
L["Bar Height"] = "Hauteur de barre"
L["Height of the small resource bar shown at the bottom of each icon. Only visible when Display Mode is set to |cffffffffBar|r."] = "Hauteur de la petite barre de ressource affichée en bas de chaque icône. Visible uniquement lorsque le Mode d'affichage est réglé sur |cffffffffBarre|r."
L["Effects"] = "Effets"
L["Visual effects on ability icons for active buffs, debuffs, and procs."] = "Effets visuels sur les icônes de capacités pour les améliorations, affaiblissements et procs actifs."
L["Aura Tracking"] = "Suivi d'auras"
L["Abilities that apply buffs or debuffs (like Intimidating Shout, Rend, Renew) show the active duration with a glow while the effect is on a target. After it expires, the cooldown is shown. Disable if you only want to see cooldowns."] = "Les capacités qui appliquent des améliorations ou des affaiblissements (comme Cri intimidant, Déchirure, Rénovation) affichent la durée active avec une lueur tant que l'effet est sur une cible. Après son expiration, le temps de recharge est affiché. Désactivez si vous ne voulez voir que les temps de recharge."
L["Target-of-Target Support"] = "Prise en charge cible de la cible"
L["Also check for your buffs and debuffs on your target's target. Useful for healers tracking HoTs on the tank's target.\n\nExamples:\n- Target the boss, see your heals on the tank (the boss's target)\n- Target the tank, see your DoTs on the boss (the tank's target)"] = "Vérifie également vos améliorations et affaiblissements sur la cible de votre cible. Utile pour les soigneurs qui suivent les soins sur la durée sur la cible du tank.\n\nExemples :\n- Ciblez le boss, voyez vos soins sur le tank (la cible du boss)\n- Ciblez le tank, voyez vos dégâts sur la durée sur le boss (la cible du tank)"
L["Aura Spiral Opacity"] = "Opacité de la spirale d'aura"
L["How dark the spiral overlay appears when tracking active buff or aura durations on icons. Lower values make it more subtle and transparent.\n\nNote: Even at 100%, the spiral won't completely obscure the icon — WoW's cooldown texture has built-in transparency."] = "Le niveau d'obscurité de la spirale lors du suivi des durées d'amélioration ou d'aura actives sur les icônes. Les valeurs plus faibles la rendent plus subtile et transparente.\n\nNote : même à 100 %, la spirale ne masquera pas complètement l'icône — la texture de temps de recharge de WoW possède une transparence intégrée."
L["Cast Feedback"] = "Retour de lancement"
L["Plays a brief 'pop' animation (the icon scales up slightly then back down) whenever you successfully cast an ability. Gives satisfying visual feedback that your spell went off. Select which rows show this animation."] = "Joue une brève animation de « pop » (l'icône s'agrandit légèrement puis revient à la normale) chaque fois que vous lancez une capacité avec succès. Donne un retour visuel satisfaisant confirmant que votre sort est parti. Sélectionnez les rangées qui affichent cette animation."
L["Pop Scale"] = "Échelle du pop"
L["How much the icon briefly grows when you cast a spell. Higher values = bigger pop."] = "De combien l'icône s'agrandit brièvement lorsque vous lancez un sort. Valeurs plus élevées = pop plus grand."
L["Ready Glow"] = "Lueur de disponibilité"
L["Shows a glowing border around ability icons when they come off cooldown and are ready to use. Only triggers while in combat. Select which rows display this effect."] = "Affiche une bordure lumineuse autour des icônes de capacités lorsqu'elles sortent de temps de recharge et sont prêtes à l'emploi. Ne se déclenche qu'en combat. Sélectionnez les rangées qui affichent cet effet."
L["Re-trigger Glow"] = "Redéclencher la lueur"
L["Which rows re-trigger the glow whenever an ability becomes usable again (not just the first time).\n\nOn these rows, the glow plays again every time usability changes (e.g., gaining enough resources, target entering Execute range). Rows not selected here play the glow only once per cooldown cycle.\n\nNote: Reactive abilities (like Execute or Overpower) always re-trigger regardless of this setting."] = "Les rangées qui redéclenchent la lueur chaque fois qu'une capacité redevient utilisable (pas seulement la première fois).\n\nSur ces rangées, la lueur se rejoue à chaque changement d'utilisabilité (p. ex. gain de ressources suffisantes, cible entrant dans la portée d'Exécution). Les rangées non sélectionnées ici ne jouent la lueur qu'une seule fois par cycle de temps de recharge.\n\nNote : les capacités réactives (comme Exécution ou Réprimande) se redéclenchent toujours, quel que soit ce réglage."
L["Duration"] = "Durée"
L["How long each ready glow animation lasts (in seconds). After this time, the glow fades out. On rows with Re-trigger Glow, the glow will re-trigger at this interval each time usability changes."] = "La durée de chaque animation de lueur de disponibilité (en secondes). Après ce délai, la lueur s'estompe. Sur les rangées avec Redéclencher la lueur, la lueur se redéclenchera à cet intervalle à chaque changement d'utilisabilité."
L["Pre-trigger Time"] = "Délai de pré-déclenchement"
L["Begin the glow this many seconds before the cooldown completes, so you can prepare your next action. At 0, the glow only appears once the cooldown is fully complete."] = "Démarre la lueur ce nombre de secondes avant la fin du temps de recharge, afin que vous puissiez préparer votre prochaine action. À 0, la lueur n'apparaît qu'une fois le temps de recharge entièrement terminé."
L["Queued Highlight"] = "Surbrillance de mise en file"
L["Brightens the icon of your next queued ability. Most noticeable on \"next melee\" attacks like Heroic Strike or Maul that stay queued until your next swing, but you may also see a brief flash on any ability queued during a cast or GCD."] = "Éclaircit l'icône de votre prochaine capacité mise en file. C'est surtout visible sur les attaques « au prochain corps à corps » comme Frappe héroïque ou Mutilation qui restent en file jusqu'à votre prochain coup, mais vous pouvez aussi voir un bref éclair sur toute capacité mise en file pendant un incantation ou un TdRG."
L["Indicators"] = "Indicateurs"
L["Range checking, sorting, and keybind display on ability icons."] = "Vérification de portée, tri et affichage des raccourcis sur les icônes de capacités."
L["Range Indicator"] = "Indicateur de portée"
L["Shows a red overlay on spell icons when your current target is out of range. Shows when an ability is usable but out of range — even during cooldown, giving you a heads-up on positioning. When resources are insufficient, the grey/resource indicators take priority instead.\n\nNote: Only shows when you have a target. Spells without a range component (self-buffs, etc.) are not affected."] = "Affiche une surimpression rouge sur les icônes de sorts lorsque votre cible actuelle est hors de portée. S'affiche lorsqu'une capacité est utilisable mais hors de portée — même pendant le temps de recharge, vous donnant une indication sur le positionnement. Lorsque les ressources sont insuffisantes, les indicateurs de grisage/ressource ont la priorité à la place.\n\nNote : ne s'affiche que lorsque vous avez une cible. Les sorts sans composante de portée (auto-améliorations, etc.) ne sont pas affectés."
L["Dynamic Sorting"] = "Tri dynamique"
L["Automatically reorders icons left-to-right by remaining cooldown, so abilities that are almost ready appear first.\n\nUseful for DOT classes (see which debuff is closest to expiring) and cooldown-heavy classes (see which ability is ready next).\n\nTie-breaker: When multiple abilities are ready, they sort by their original row position — so your row order acts as a priority list and the leftmost icon is always the next best spell to cast."] = "Réorganise automatiquement les icônes de gauche à droite selon le temps de recharge restant, afin que les capacités presque prêtes apparaissent en premier.\n\nUtile pour les classes à dégâts sur la durée (voir quel affaiblissement est le plus proche d'expirer) et les classes à nombreux temps de recharge (voir quelle capacité sera prête ensuite).\n\nDépartage : lorsque plusieurs capacités sont prêtes, elles sont triées selon leur position d'origine dans la rangée — votre ordre de rangée agit donc comme une liste de priorités, et l'icône la plus à gauche est toujours le meilleur prochain sort à lancer."
L["Smooth Sorting"] = "Tri fluide"
L["Icons slide smoothly into their new position when the sort order changes. Disable for instant repositioning."] = "Les icônes glissent en douceur vers leur nouvelle position lorsque l'ordre de tri change. Désactivez pour un repositionnement instantané."
L["Keybinds"] = "Raccourcis"
L["Displays the keyboard shortcut for each ability in the bottom-right corner. VeevHUD scans your action bars to find where each spell is placed. Modifiers are abbreviated: Shift=S, Ctrl=C, Alt=A (e.g., Shift+X becomes 'SX').\n\nSupports Bartender4, ElvUI, Dominos. If you move spells or change keybinds, the display updates automatically."] = "Affiche le raccourci clavier de chaque capacité dans le coin inférieur droit. VeevHUD analyse vos barres d'action pour trouver où chaque sort est placé. Les modificateurs sont abrégés : Maj=S, Ctrl=C, Alt=A (p. ex. Maj+X devient « SX »).\n\nPrend en charge Bartender4, ElvUI, Dominos. Si vous déplacez des sorts ou changez des raccourcis, l'affichage se met à jour automatiquement."
L["Text Size"] = "Taille du texte"
L["The font size for keybind text in pixels. Larger values make the text more readable but take up more space on the icon."] = "La taille de police du texte des raccourcis en pixels. Les valeurs plus grandes rendent le texte plus lisible mais occupent plus d'espace sur l'icône."
L["Item Counts"] = "Nombre d'objets"
L["Reagent Count"] = "Nombre de composants"
L["Shows the number of reagents you have in the top-right corner of spell icons that consume reagents on cast. Examples: Soul Shards on warlock abilities, seeds on Rebirth, Flash Powder on Vanish, Ankhs on Reincarnation."] = "Affiche le nombre de composants dont vous disposez dans le coin supérieur droit des icônes de sorts qui consomment des composants au lancement. Exemples : fragments d'âme pour les capacités de démoniste, graines pour Renaissance, poudre de disparition pour Disparition, ankhs pour Réincarnation."
L["Count All Ranks"] = "Compter tous les rangs"
L["When enabled, counts reagents for all spell ranks combined (e.g., all seed types for Rebirth). When disabled, only counts the reagent for your highest learned rank."] = "Lorsqu'il est activé, compte les composants de tous les rangs de sort combinés (p. ex. tous les types de graines pour Renaissance). Lorsqu'il est désactivé, ne compte que le composant de votre rang appris le plus élevé."
L["Consumable Count"] = "Nombre de consommables"
L["Shows your current bag count in the top-right corner of consumable icons (potions, runes, etc.)."] = "Affiche le nombre actuel dans votre sac dans le coin supérieur droit des icônes de consommables (potions, runes, etc.)."
L["Status Bars"] = "Barres d'état"
L["Resource Bar"] = "Barre de ressource"
L["Your character's resource bar (mana, rage, or energy)."] = "La barre de ressource de votre personnage (mana, rage ou énergie)."
L["Shows a bar displaying your current mana, rage, or energy (depending on your class). Appears between the health bar and the ability icon rows."] = "Affiche une barre indiquant votre mana, rage ou énergie actuel (selon votre classe). Apparaît entre la barre de vie et les rangées d'icônes de capacités."
L["Width"] = "Largeur"
L["How wide the resource bar is in pixels."] = "La largeur de la barre de ressource en pixels."
L["Height"] = "Hauteur"
L["How tall/thick the resource bar is in pixels. Changing this will automatically adjust the position of elements above it."] = "La hauteur/épaisseur de la barre de ressource en pixels. Changer cette valeur ajustera automatiquement la position des éléments situés au-dessus."
L["Text"] = "Texte"
L["Text Format"] = "Format du texte"
L["Controls what text is shown on the resource bar.\n\n|cffffffffCurrent|r — Shows your actual resource (e.g., 4523).\n|cffffffffPercent|r — Shows your resource percentage (e.g., 85%).\n|cffffffffBoth|r — Shows both (e.g., 4523 (85%)).\n|cffffffffCurrent / Max|r — Shows current and maximum (e.g., 4523 / 5320).\n|cffffffffCurrent / Max (%)|r — Shows current, maximum, and percentage (e.g., 4523 / 5320 (85%)).\n|cffffffffDeficit|r — Shows how much is missing (e.g., -797). Hidden at full.\n|cffffffffNone|r — Hides the text entirely."] = "Contrôle le texte affiché sur la barre de ressource.\n\n|cffffffffActuel|r — Affiche votre ressource réelle (p. ex. 4523).\n|cffffffffPourcentage|r — Affiche le pourcentage de votre ressource (p. ex. 85 %).\n|cffffffffLes deux|r — Affiche les deux (p. ex. 4523 (85 %)).\n|cffffffffActuel / Max|r — Affiche l'actuel et le maximum (p. ex. 4523 / 5320).\n|cffffffffActuel / Max (%)|r — Affiche l'actuel, le maximum et le pourcentage (p. ex. 4523 / 5320 (85 %)).\n|cffffffffDéficit|r — Affiche ce qui manque (p. ex. -797). Masqué à pleine ressource.\n|cffffffffAucun|r — Masque entièrement le texte."
L["Number Format"] = "Format des nombres"
L["Controls how numbers are displayed.\n\n|cffffffffAbbreviated|r — Large numbers shortened (e.g., 4.5k, 1.2m).\n|cffffffffFull|r — Whole numbers (e.g., 4523).\n|cffffffffComma|r — Comma-separated (e.g., 4,523)."] = "Contrôle l'affichage des nombres.\n\n|cffffffffAbrégé|r — Grands nombres raccourcis (p. ex. 4.5k, 1.2m).\n|cffffffffComplet|r — Nombres entiers (p. ex. 4523).\n|cffffffffVirgule|r — Séparés par une virgule (p. ex. 4,523)."
L["Font size for the resource text. Larger sizes are easier to read but may overflow small bars."] = "Taille de police du texte de ressource. Les tailles plus grandes sont plus faciles à lire mais peuvent déborder des petites barres."
L["Text outline style for the resource bar."] = "Style de contour du texte pour la barre de ressource."
L["Default Color"] = "Couleur par défaut"
L["Colors the bar based on your resource type — blue for mana, red for rage, yellow for energy. Uncheck to use a custom color instead.\n\n"] = "Colore la barre selon votre type de ressource — bleu pour le mana, rouge pour la rage, jaune pour l'énergie. Décochez pour utiliser une couleur personnalisée à la place.\n\n"
L["Overridden by Innervate Highlight (mana) and Rage Highlight (rage) when those are active."] = "Remplacé par la Mise en évidence d'Innervation (mana) et la Mise en évidence de rage (rage) lorsqu'elles sont actives."
L["The custom color for the resource bar. Only used when Use Resource Color is unchecked.\n\n"] = "La couleur personnalisée de la barre de ressource. Utilisée uniquement lorsque Utiliser la couleur de ressource est décoché.\n\n"
L["Innervate Highlight"] = "Mise en évidence d'Innervation"
L["Changes the mana bar color when the Innervate buff is active, giving you immediate visual feedback that your mana regeneration is boosted."] = "Change la couleur de la barre de mana lorsque l'amélioration Innervation est active, vous donnant un retour visuel immédiat indiquant que votre régénération de mana est augmentée."
L["Color"] = "Couleur"
L["The color the resource bar changes to during Innervate."] = "La couleur que prend la barre de ressource pendant Innervation."
L["Master toggle for rage bar coloring. When enabled, the bar changes color based on rage thresholds (e.g., flag rage cap risk) and when Heroic Strike or Cleave is queued onto your next swing."] = "Bascule principale pour la coloration de la barre de rage. Lorsqu'elle est activée, la barre change de couleur selon les seuils de rage (p. ex. signaler le risque de plafond de rage) et lorsque Frappe héroïque ou Cisaillement est mis en file pour votre prochain coup."
L["Rage Thresholds"] = "Seuils de rage"
L["Threshold Coloring"] = "Coloration par seuils"
L["Recolor the bar based on current rage. Three tiers (low/mid/high) gated by two thresholds."] = "Recolore la barre selon la rage actuelle. Trois paliers (bas/moyen/haut) délimités par deux seuils."
L["Low Threshold"] = "Seuil bas"
L["Below this rage value, the bar uses the Low color. Above it (and below the High threshold), the Mid color."] = "En dessous de cette valeur de rage, la barre utilise la couleur Bas. Au-dessus (et en dessous du seuil Haut), la couleur Moyen."
L["High Threshold"] = "Seuil haut"
L["At or above this rage value, the bar uses the High color (e.g., bright red to flag rage cap risk)."] = "À cette valeur de rage ou au-dessus, la barre utilise la couleur Haut (p. ex. rouge vif pour signaler le risque de plafond de rage)."
L["Low Color"] = "Couleur Bas"
L["Bar color when rage is below the Low threshold."] = "Couleur de la barre lorsque la rage est en dessous du seuil Bas."
L["Mid Color"] = "Couleur Moyen"
L["Bar color when rage is between the Low and High thresholds."] = "Couleur de la barre lorsque la rage est entre les seuils Bas et Haut."
L["High Color"] = "Couleur Haut"
L["Bar color when rage is at or above the High threshold."] = "Couleur de la barre lorsque la rage est au seuil Haut ou au-dessus."
L["Queued Ability Override"] = "Remplacement par capacité en file"
L["Queue Override"] = "Remplacement de file"
L["When a swing-reset ability (Heroic Strike, Cleave, Maul) is queued onto your next swing, override the threshold color with a per-ability color."] = "Lorsqu'une capacité réinitialisant le coup (Frappe héroïque, Cisaillement, Mutilation) est mise en file pour votre prochain coup, remplace la couleur de seuil par une couleur propre à la capacité."
L["Bar color when %s is queued onto your next swing."] = "Couleur de la barre lorsque %s est mis en file pour votre prochain coup."
L["Rage Highlight"] = "Mise en évidence de rage"
L["Shows a bright highlight at the bar's current fill point — the glowing line where the filled and empty portions meet. Adds visual polish."] = "Affiche une mise en évidence lumineuse au point de remplissage actuel de la barre — la ligne lumineuse où les portions pleine et vide se rejoignent. Ajoute une touche visuelle."
L["How wide the spark highlight is in pixels. Larger values create a broader, more prominent glow."] = "La largeur de la mise en évidence d'étincelle en pixels. Les valeurs plus grandes créent une lueur plus large et plus marquée."
L["Overflow"] = "Débordement"
L["How far the spark glow extends beyond the top and bottom edges of the bar (in pixels). Higher values create a taller spark that 'overflows' past the bar."] = "La distance à laquelle la lueur de l'étincelle dépasse les bords supérieur et inférieur de la barre (en pixels). Les valeurs plus élevées créent une étincelle plus haute qui « déborde » de la barre."
L["Hide at Full/Empty"] = "Masquer si plein/vide"
L["Hides the spark when the bar is completely full or completely empty, since there's no meaningful fill point to highlight in those states."] = "Masque l'étincelle lorsque la barre est complètement pleine ou complètement vide, puisqu'il n'y a pas de point de remplissage pertinent à mettre en évidence dans ces états."
L["Overlays"] = "Surimpressions"
L["Predicted Cost"] = "Coût prédit"
L["Shows a darkened section on the resource bar representing the cost of abilities you are currently casting or have queued (e.g., Heroic Strike, Cleave). Gives you a preview of where your resource will be after the ability completes."] = "Affiche une section assombrie sur la barre de ressource représentant le coût des capacités que vous êtes en train de lancer ou que vous avez mises en file (p. ex. Frappe héroïque, Cisaillement). Vous donne un aperçu du niveau de votre ressource une fois la capacité terminée."
L["Energy Ticker"] = "Indicateur de tic d'énergie"
L["Shows progress toward the next energy tick (energy regenerates every 2 seconds). Helps you time abilities to maximize energy efficiency."] = "Affiche la progression vers le prochain tic d'énergie (l'énergie se régénère toutes les 2 secondes). Vous aide à minuter vos capacités pour maximiser l'efficacité de votre énergie."
L["Style"] = "Style"
L["|cffffffffTicker Bar|r — Shows a separate thin bar below the resource bar that fills as the next tick approaches.\n\n|cffffffffSpark|r — Shows a moving spark overlay on the resource bar itself, which is more subtle."] = "|cffffffffBarre de tic|r — Affiche une fine barre distincte sous la barre de ressource qui se remplit à l'approche du prochain tic.\n\n|cffffffffÉtincelle|r — Affiche une surimpression d'étincelle mobile sur la barre de ressource elle-même, ce qui est plus subtil."
L["Show at Full Energy"] = "Afficher à pleine énergie"
L["Keep the tick indicator running even when at full energy. Useful for timing openers — you can see exactly when the next tick will occur and use energy right before it arrives."] = "Garde l'indicateur de tic actif même à pleine énergie. Utile pour minuter vos ouvertures — vous pouvez voir exactement quand le prochain tic surviendra et utiliser de l'énergie juste avant son arrivée."
L["Bar Settings"] = "Réglages de la barre"
L["How tall the energy ticker bar is in pixels."] = "La hauteur de la barre de tic d'énergie en pixels."
L["Bar Offset"] = "Décalage de la barre"
L["Moves the energy ticker bar up or down relative to the resource bar. Positive values move it down, negative values move it up."] = "Déplace la barre de tic d'énergie vers le haut ou le bas par rapport à la barre de ressource. Les valeurs positives la déplacent vers le bas, les valeurs négatives vers le haut."
L["The color used for the energy ticker bar."] = "La couleur utilisée pour la barre de tic d'énergie."
L["Spark Settings"] = "Réglages de l'étincelle"
L["Spark Width"] = "Largeur de l'étincelle"
L["How wide the tick spark is in pixels."] = "La largeur de l'étincelle de tic en pixels."
L["Spark Height"] = "Hauteur de l'étincelle"
L["How tall the tick spark is relative to the resource bar. Values above 1.0 make the spark extend beyond the bar edges."] = "La hauteur de l'étincelle de tic par rapport à la barre de ressource. Les valeurs supérieures à 1,0 font dépasser l'étincelle au-delà des bords de la barre."
L["Mana Ticker"] = "Indicateur de tic de mana"
L["Shows a moving spark on the resource bar indicating when your next mana tick will arrive. Mana regenerates in periodic ticks, and casting at the wrong time can delay your next tick — this indicator helps you cast at the optimal moment."] = "Affiche une étincelle mobile sur la barre de ressource indiquant quand votre prochain tic de mana arrivera. Le mana se régénère par tics périodiques, et lancer un sort au mauvais moment peut retarder votre prochain tic — cet indicateur vous aide à lancer au moment optimal."
L["|cffffffffOutside 5 Second Rule|r — Only shows the tick timer when you haven't cast a spell in the last 5 seconds (when you're getting full spirit-based mana regeneration).\n\n|cffffffffNext Full Tick|r (Recommended) — Always active. After you cast a spell, it predicts exactly when your first full-rate mana tick will arrive and counts down to it. Cast right after the tick completes to get the most mana before your next spell."] = "|cffffffffHors règle des 5 secondes|r — N'affiche le minuteur de tic que lorsque vous n'avez pas lancé de sort durant les 5 dernières secondes (lorsque vous bénéficiez de la pleine régénération de mana basée sur l'esprit).\n\n|cffffffffProchain tic complet|r (recommandé) — Toujours actif. Après avoir lancé un sort, il prédit exactement quand votre premier tic de mana à plein taux arrivera et en effectue le décompte. Lancez juste après la fin du tic pour obtenir le plus de mana avant votre prochain sort."
L["How wide the mana tick spark is in pixels."] = "La largeur de l'étincelle de tic de mana en pixels."
L["How tall the mana tick spark is relative to the resource bar. Values above 1.0 make it extend beyond the bar edges."] = "La hauteur de l'étincelle de tic de mana par rapport à la barre de ressource. Les valeurs supérieures à 1,0 la font dépasser au-delà des bords de la barre."
L["Mana Bar (Druid)"] = "Barre de mana (druide)"
L["Shows a secondary mana bar below the resource bar while in Cat Form or Bear Form, so you can monitor mana for shifting and casting."] = "Affiche une barre de mana secondaire sous la barre de ressource en forme de félin ou d'ours, afin que vous puissiez surveiller votre mana pour changer de forme et lancer des sorts."
L["Show a secondary mana bar below the resource bar while shapeshifted."] = "Affiche une barre de mana secondaire sous la barre de ressource lorsque vous êtes métamorphosé."
L["How tall the secondary mana bar is in pixels."] = "La hauteur de la barre de mana secondaire en pixels."
L["Show Spark"] = "Afficher l'étincelle"
L["Shows a glowing spark at the current fill position on the mana bar."] = "Affiche une étincelle lumineuse à la position de remplissage actuelle sur la barre de mana."
L["The color used for the secondary mana bar."] = "La couleur utilisée pour la barre de mana secondaire."
L["Show Mana Ticker"] = "Afficher le tic de mana"
L["Shows the mana tick spark on this bar while in form. When disabled, the mana ticker only appears on the main resource bar in caster form."] = "Affiche l'étincelle de tic de mana sur cette barre lorsque vous êtes en forme. Lorsqu'il est désactivé, l'indicateur de tic de mana n'apparaît que sur la barre de ressource principale en forme d'incantateur."
L["Form Cost Marker"] = "Marqueur de coût de forme"
L["Shows a vertical line on the mana bar when your mana is too low to re-enter your current shapeshift form. The line indicates the mana threshold needed, so you can see how close you are to being able to shift back."] = "Affiche une ligne verticale sur la barre de mana lorsque votre mana est trop bas pour reprendre votre forme métamorphosée actuelle. La ligne indique le seuil de mana nécessaire, afin que vous puissiez voir à quel point vous êtes proche de pouvoir reprendre la forme."
L["Controls what text is shown on the Druid mana bar.\n\n|cffffffffCurrent|r — Shows your actual mana.\n|cffffffffPercent|r — Shows your mana percentage.\n|cffffffffBoth|r — Shows both.\n|cffffffffCurrent / Max|r — Shows current and maximum.\n|cffffffffCurrent / Max (%)|r — Shows current, maximum, and percentage.\n|cffffffffDeficit|r — Shows how much is missing. Hidden at full.\n|cffffffffNone|r — Hides the text."] = "Contrôle le texte affiché sur la barre de mana du druide.\n\n|cffffffffActuel|r — Affiche votre mana réel.\n|cffffffffPourcentage|r — Affiche votre pourcentage de mana.\n|cffffffffLes deux|r — Affiche les deux.\n|cffffffffActuel / Max|r — Affiche l'actuel et le maximum.\n|cffffffffActuel / Max (%)|r — Affiche l'actuel, le maximum et le pourcentage.\n|cffffffffDéficit|r — Affiche ce qui manque. Masqué à plein.\n|cffffffffAucun|r — Masque le texte."
L["Controls how numbers are displayed."] = "Contrôle l'affichage des nombres."
L["Font size for the mana bar text."] = "Taille de police du texte de la barre de mana."
L["Text outline style for the druid mana bar."] = "Style de contour du texte pour la barre de mana du druide."
L["Health Bar"] = "Barre de vie"
L["Your character's health bar with heal prediction."] = "La barre de vie de votre personnage avec prédiction de soins."
L["Shows a bar displaying your current health above the resource bar. Gives you a quick glance at your survivability without looking at your unit frame."] = "Affiche une barre indiquant votre vie actuelle au-dessus de la barre de ressource. Vous donne un aperçu rapide de votre capacité de survie sans regarder votre cadre d'unité."
L["How wide the health bar is in pixels."] = "La largeur de la barre de vie en pixels."
L["How tall/thick the health bar is in pixels. Changing this will automatically adjust the position of elements above it."] = "La hauteur/épaisseur de la barre de vie en pixels. Changer cette valeur ajustera automatiquement la position des éléments situés au-dessus."
L["Controls what text is shown on the health bar.\n\n|cffffffffCurrent|r — Shows your actual health (e.g., 3256).\n|cffffffffPercent|r — Shows your health percentage (e.g., 71%).\n|cffffffffBoth|r — Shows both (e.g., 3256 (71%)).\n|cffffffffCurrent / Max|r — Shows current and maximum (e.g., 3256 / 4580).\n|cffffffffCurrent / Max (%)|r — Shows current, maximum, and percentage (e.g., 3256 / 4580 (71%)).\n|cffffffffDeficit|r — Shows how much health is missing (e.g., -1324). Hidden at full.\n|cffffffffNone|r — Hides the text entirely."] = "Contrôle le texte affiché sur la barre de vie.\n\n|cffffffffActuel|r — Affiche votre vie réelle (p. ex. 3256).\n|cffffffffPourcentage|r — Affiche votre pourcentage de vie (p. ex. 71 %).\n|cffffffffLes deux|r — Affiche les deux (p. ex. 3256 (71 %)).\n|cffffffffActuel / Max|r — Affiche l'actuel et le maximum (p. ex. 3256 / 4580).\n|cffffffffActuel / Max (%)|r — Affiche l'actuel, le maximum et le pourcentage (p. ex. 3256 / 4580 (71 %)).\n|cffffffffDéficit|r — Affiche la vie manquante (p. ex. -1324). Masqué à pleine vie.\n|cffffffffAucun|r — Masque entièrement le texte."
L["Font size for the health text. Larger sizes are easier to read but may overflow small bars."] = "Taille de police du texte de vie. Les tailles plus grandes sont plus faciles à lire mais peuvent déborder des petites barres."
L["Text outline style for the health bar."] = "Style de contour du texte pour la barre de vie."
L["Use Class Color"] = "Utiliser la couleur de classe"
L["Colors the health bar using your class color (e.g., brown for Warriors, purple for Warlocks) instead of the standard green."] = "Colore la barre de vie avec votre couleur de classe (p. ex. marron pour les guerriers, violet pour les démonistes) au lieu du vert standard."
L["The custom color for the health bar. Only used when Use Class Color is unchecked."] = "La couleur personnalisée de la barre de vie. Utilisée uniquement lorsque Utiliser la couleur de classe est décoché."
L["Heal Prediction"] = "Prédiction de soins"
L["Shows a lighter overlay on the health bar representing incoming heals. The overlay extends from your current health into the missing health area, giving you a preview of where your health will be after heals land."] = "Affiche une surimpression plus claire sur la barre de vie représentant les soins entrants. La surimpression s'étend de votre vie actuelle vers la zone de vie manquante, vous donnant un aperçu du niveau de votre vie une fois les soins reçus."
L["Pet Health Bar"] = "Barre de vie du familier"
L["Your pet's health bar. Automatically hides when no pet is active."] = "La barre de vie de votre familier. Se masque automatiquement lorsqu'aucun familier n'est actif."
L["Shows a bar displaying your pet's current health. Automatically hides when you have no active pet."] = "Affiche une barre indiquant la vie actuelle de votre familier. Se masque automatiquement lorsque vous n'avez aucun familier actif."
L["How wide the pet health bar is in pixels."] = "La largeur de la barre de vie du familier en pixels."
L["How tall/thick the pet health bar is in pixels."] = "La hauteur/épaisseur de la barre de vie du familier en pixels."
L["Controls what text is shown on the pet health bar.\n\n|cffffffffCurrent|r — Shows actual health.\n|cffffffffPercent|r — Shows health percentage.\n|cffffffffBoth|r — Shows both.\n|cffffffffCurrent / Max|r — Shows current and maximum.\n|cffffffffCurrent / Max (%)|r — Shows current, maximum, and percentage.\n|cffffffffDeficit|r — Shows how much health is missing. Hidden at full.\n|cffffffffNone|r — Hides the text."] = "Contrôle le texte affiché sur la barre de vie du familier.\n\n|cffffffffActuel|r — Affiche la vie réelle.\n|cffffffffPourcentage|r — Affiche le pourcentage de vie.\n|cffffffffLes deux|r — Affiche les deux.\n|cffffffffActuel / Max|r — Affiche l'actuel et le maximum.\n|cffffffffActuel / Max (%)|r — Affiche l'actuel, le maximum et le pourcentage.\n|cffffffffDéficit|r — Affiche la vie manquante. Masqué à pleine vie.\n|cffffffffAucun|r — Masque le texte."
L["Font size for the pet health text."] = "Taille de police du texte de vie du familier."
L["Text outline style for the pet health bar."] = "Style de contour du texte pour la barre de vie du familier."
L["The color for the pet health bar."] = "La couleur de la barre de vie du familier."
L["Shows a lighter overlay on the pet health bar representing incoming heals."] = "Affiche une surimpression plus claire sur la barre de vie du familier représentant les soins entrants."
L["Combo Points"] = "Points de combo"
L["Horizontal combo point display below the resource bar."] = "Affichage horizontal des points de combo sous la barre de ressource."
L["Shows combo point bars below the resource bar. For Druids, this only appears while in Cat Form."] = "Affiche les barres de points de combo sous la barre de ressource. Pour les druides, cela n'apparaît qu'en forme de félin."
L["Size & Layout"] = "Taille et disposition"
L["The total width of the combo points display in pixels."] = "La largeur totale de l'affichage des points de combo en pixels."
L["The height of each combo point bar in pixels. Smaller values create a more subtle display."] = "La hauteur de chaque barre de point de combo en pixels. Les valeurs plus petites créent un affichage plus discret."
L["Bar Spacing"] = "Espacement des barres"
L["The gap in pixels between each individual combo point segment."] = "L'écart en pixels entre chaque segment individuel de point de combo."
L["The color used for active combo point segments."] = "La couleur utilisée pour les segments de points de combo actifs."
L["Aura Tracker"] = "Suivi d'auras"
L["The Aura Tracker shows small icons for important temporary buffs — class procs (Enrage, Flurry, Clearcasting), external buffs (Bloodlust, Power Infusion, Innervate), and any custom auras you add.\n\nUse the tabs above to configure which auras to show."] = "Le Suivi d'auras affiche de petites icônes pour les améliorations temporaires importantes — procs de classe (Furie, Déluge, Mensonge), améliorations externes (Sang pour sang, Infusion de puissance, Innervation) et toutes les auras personnalisées que vous ajoutez.\n\nUtilisez les onglets ci-dessus pour configurer les auras à afficher."
L["Enable Aura Tracker"] = "Activer le Suivi d'auras"
L["Master toggle for the Aura Tracker feature. When disabled, no aura icons will be shown."] = "Bascule principale pour la fonction Suivi d'auras. Lorsqu'elle est désactivée, aucune icône d'aura ne sera affichée."
L["Layout"] = "Disposition"
L["How big the aura icons are in pixels. These are typically smaller than ability icons since they're just indicators. 20-28 pixels works well for most people."] = "La taille des icônes d'auras en pixels. Elles sont généralement plus petites que les icônes de capacités puisque ce ne sont que des indicateurs. 20-28 pixels conviennent à la plupart des gens."
L["The gap in pixels between each aura icon when multiple auras are active at once."] = "L'écart en pixels entre chaque icône d'aura lorsque plusieurs auras sont actives à la fois."
L["Makes aura icons shorter by shrinking height while keeping width the same. Useful if you want compact spell rows but prefer aura icons to stay more square and readable."] = "Rend les icônes d'auras plus courtes en réduisant leur hauteur tout en conservant la même largeur. Utile si vous voulez des rangées de sorts compactes mais préférez que les icônes d'auras restent plus carrées et lisibles."
L["Glow"] = "Lueur"
L["Edge Glow"] = "Lueur de bordure"
L["Shows a glowing animated border around active aura icons, making them stand out and drawing your eye to important buffs."] = "Affiche une bordure animée lumineuse autour des icônes d'auras actives, les faisant ressortir et attirant votre regard sur les améliorations importantes."
L["Backdrop Intensity"] = "Intensité du fond"
L["Controls the brightness of the soft colored halo that appears behind each aura icon. Higher values make the glow more prominent. Set to 0 to turn it off completely."] = "Contrôle la luminosité du halo coloré doux qui apparaît derrière chaque icône d'aura. Les valeurs plus élevées rendent la lueur plus marquée. Réglez sur 0 pour la désactiver complètement."
L["Backdrop Size"] = "Taille du fond"
L["How far the backdrop glow extends outward from each aura icon. Larger values create a wider, softer halo."] = "La distance à laquelle la lueur de fond s'étend vers l'extérieur depuis chaque icône d'aura. Les valeurs plus grandes créent un halo plus large et plus doux."
L["Animation"] = "Animation"
L["Show Duration"] = "Afficher la durée"
L["Displays the remaining time on aura buffs as text on the icon. Disable if you prefer a cleaner look or if it overlaps with stack counts."] = "Affiche le temps restant des améliorations d'auras sous forme de texte sur l'icône. Désactivez si vous préférez un aspect plus épuré ou si cela chevauche le nombre de cumuls."
L["Text outline style for aura tracker text."] = "Style de contour du texte pour le suivi d'auras."
L["Slide Animation"] = "Animation de glissement"
L["When auras appear or disappear, the remaining icons smoothly slide to re-center instead of snapping instantly. Disable for instant repositioning."] = "Lorsque des auras apparaissent ou disparaissent, les icônes restantes glissent en douceur pour se recentrer au lieu de se replacer instantanément. Désactivez pour un repositionnement instantané."
L["Activation Pop"] = "Pop d'activation"
L["How much the icon briefly grows when an aura activates or refreshes. Set to 100% to disable the pop animation."] = "De combien l'icône s'agrandit brièvement lorsqu'une aura s'active ou se renouvelle. Réglez sur 100 % pour désactiver l'animation de pop."
L["Sort Order"] = "Ordre de tri"
L["How active aura icons are arranged.\n\n|cffffffffActivation Order|r — First-activated aura appears on the left, newest on the right.\n\n|cffffffffFixed|r — Icons stay in a consistent order based on spell registration (class procs first, then externals, then custom).\n\n|cffffffffLeast Remaining|r — Aura closest to expiring appears on the left. Icons re-sort as durations tick down."] = "Comment les icônes d'auras actives sont disposées.\n\n|cffffffffOrdre d'activation|r — L'aura activée en premier apparaît à gauche, la plus récente à droite.\n\n|cffffffffFixe|r — Les icônes restent dans un ordre constant basé sur l'enregistrement des sorts (procs de classe d'abord, puis externes, puis personnalisées).\n\n|cffffffffMoins de temps restant|r — L'aura la plus proche d'expirer apparaît à gauche. Les icônes se retrient à mesure que les durées s'écoulent."
L["Activation Order"] = "Ordre d'activation"
L["Fixed"] = "Fixe"
L["Least Remaining"] = "Moins de temps restant"
L["Bars"] = "Barres"
L["Auras set to \"Bar\" mode (via the Display dropdown in the aura list tabs) render as a vertical stack of timer bars below the icon row. These settings control how those bars look."] = "Les auras réglées en mode « Barre » (via le menu déroulant Affichage dans les onglets de liste d'auras) s'affichent sous forme d'une pile verticale de barres de minuteur sous la rangée d'icônes. Ces réglages contrôlent l'apparence de ces barres."
L["Bar Width"] = "Largeur de barre"
L["Width of each timer bar in pixels."] = "Largeur de chaque barre de minuteur en pixels."
L["Height of each timer bar in pixels. The spell icon is sized to match."] = "Hauteur de chaque barre de minuteur en pixels. L'icône du sort est dimensionnée en conséquence."
L["Vertical gap in pixels between stacked bars."] = "Écart vertical en pixels entre les barres empilées."
L["Font size for the bar's name and timer text."] = "Taille de police du nom et du texte de minuteur de la barre."
L["Text outline style for bar text."] = "Style de contour du texte des barres."
L["Fallback fill color for bars whose spell has no icon-sampled color (most do). Each aura's color is normally taken from its icon; you can override per aura in the aura list tabs."] = "Couleur de remplissage de repli pour les barres dont le sort n'a pas de couleur échantillonnée depuis l'icône (la plupart en ont une). La couleur de chaque aura est normalement tirée de son icône ; vous pouvez la remplacer par aura dans les onglets de liste d'auras."
L["Show Icon"] = "Afficher l'icône"
L["Show the spell icon at the left edge of each bar."] = "Affiche l'icône du sort au bord gauche de chaque barre."
L["Show Name"] = "Afficher le nom"
L["Show the aura name on each bar."] = "Affiche le nom de l'aura sur chaque barre."
L["Show Timer"] = "Afficher le minuteur"
L["Show the remaining-time text on each bar."] = "Affiche le texte du temps restant sur chaque barre."
L["Show a spark at the fill edge of each bar."] = "Affiche une étincelle au bord de remplissage de chaque barre."
L["Default Sound"] = "Son par défaut"
L["Sound to play when any aura activates. Individual auras can override this in the aura list tabs."] = "Son à jouer lorsqu'une aura s'active. Les auras individuelles peuvent remplacer ce réglage dans les onglets de liste d'auras."
L["Play on Refresh"] = "Jouer au renouvellement"
L["Also play the sound when an aura refreshes (is reapplied while already active). Useful for procs like Mace Stun where each trigger matters. Individual auras can override this in the aura list tabs."] = "Joue aussi le son lorsqu'une aura se renouvelle (est réappliquée alors qu'elle est déjà active). Utile pour les procs comme Étourdissement à la masse où chaque déclenchement compte. Les auras individuelles peuvent remplacer ce réglage dans les onglets de liste d'auras."
L["Swing Bar"] = "Barre de coups"
L["Your character automatically fires auto-shots on a timer. If you cast an ability too late in the timer, it 'clips' (delays) your next auto-shot, costing you DPS. The bar turns green when it's safe to cast and red when casting would clip. Once you learn Steady Shot, a yellow zone appears for the window where Steady Shot would clip but instants and movement are still safe."] = "Votre personnage tire automatiquement des tirs automatiques selon un minuteur. Si vous lancez une capacité trop tard dans le minuteur, cela « tronque » (retarde) votre prochain tir automatique, vous faisant perdre des DPS. La barre devient verte quand il est sûr de lancer un sort et rouge quand cela tronquerait. Une fois Tir assuré appris, une zone jaune apparaît pour la fenêtre où Tir assuré tronquerait mais où les sorts instantanés et le déplacement restent sûrs."
L["Seal twisting lets you get two seal procs on a single melee swing by swapping seals right before the hit lands. The bar turns green during the twist window — the last ~0.4 seconds before impact — telling you when to swap to your second seal."] = "L'alternance de sceaux vous permet d'obtenir deux procs de sceau sur un seul coup de corps à corps en changeant de sceau juste avant que le coup ne porte. La barre devient verte pendant la fenêtre d'alternance — les ~0,4 dernières secondes avant l'impact — vous indiquant quand passer à votre second sceau."
L["Tracks your melee swing timer — a bar that fills up as your next auto-attack approaches. Auto-hides between pulls."] = "Suit votre minuteur de coups de corps à corps — une barre qui se remplit à l'approche de votre prochaine attaque automatique. Se masque automatiquement entre les pulls."
L["Two bars track your main-hand and off-hand swing timers. When both weapons swing at the same time (synced), your Flurry haste charges aren't wasted on isolated off-hand hits, and Windfury extra attacks land alongside your normal swings. Bars turn green when synced and red when desynced — meaning one weapon has drifted ahead of the other."] = "Deux barres suivent les minuteurs de coups de votre main droite et de votre main gauche. Lorsque les deux armes frappent en même temps (synchronisées), vos charges de hâte de Déluge ne sont pas gaspillées sur des coups de main gauche isolés, et les attaques supplémentaires de Furie-des-vents surviennent en même temps que vos coups normaux. Les barres deviennent vertes quand elles sont synchronisées et rouges quand elles sont désynchronisées — c'est-à-dire qu'une arme a dérivé en avance sur l'autre."
L["Tracks your melee swing timer. Slam resets this timer, so for maximum DPS you want to Slam right after a swing lands (when the bar reaches the end and resets). This avoids losing auto-attack time to the Slam cast.\n\n"] = "Suit votre minuteur de coups de corps à corps. Choc réinitialise ce minuteur, donc pour un DPS maximal vous voulez utiliser Choc juste après qu'un coup porte (lorsque la barre atteint la fin et se réinitialise). Cela évite de perdre du temps d'attaque automatique à cause de l'incantation de Choc.\n\n"
L["Tracks your melee swing timer — a bar that fills up as your next auto-attack approaches. Auto-hides between pulls.\n\n"] = "Suit votre minuteur de coups de corps à corps — une barre qui se remplit à l'approche de votre prochaine attaque automatique. Se masque automatiquement entre les pulls.\n\n"
L["Tracks your auto-attack timer for wanding or melee. Only appears while actively attacking and auto-hides when you stop."] = "Suit votre minuteur d'attaque automatique pour la baguette ou le corps à corps. N'apparaît que lorsque vous attaquez activement et se masque automatiquement lorsque vous vous arrêtez."
L["Tracks your melee swing timer. Shows separate main-hand and off-hand bars when dual-wielding."] = "Suit votre minuteur de coups de corps à corps. Affiche des barres distinctes pour la main droite et la main gauche lorsque vous combattez à deux armes."
L["Tracks your melee swing timer in Cat or Bear Form. Bear Form's 2.5s swing is useful for timing Maul. Auto-hides when not actively swinging."] = "Suit votre minuteur de coups de corps à corps en forme de félin ou d'ours. Le coup de 2,5 s de la forme d'ours est utile pour minuter Mutilation. Se masque automatiquement lorsque vous ne frappez pas activement."
L["Shows a weapon swing timer bar that fills as your next auto-attack approaches. Includes class-specific colored zones: Hunter shot clipping, Ret Paladin seal twisting, Enhancement/Warrior dual-wield sync. Auto-hides when not actively swinging."] = "Affiche une barre de minuteur de coups d'arme qui se remplit à l'approche de votre prochaine attaque automatique. Inclut des zones colorées propres à chaque classe : troncature de tir du chasseur, alternance de sceaux du paladin Vindicte, synchronisation à deux armes Amélioration/guerrier. Se masque automatiquement lorsque vous ne frappez pas activement."
L["Width of the swing bar in pixels."] = "Largeur de la barre de coups en pixels."
L["Height of the swing bar in pixels (single weapon). Per-class/spec: each class or spec remembers its own height."] = "Hauteur de la barre de coups en pixels (arme unique). Par classe/spécialisation : chaque classe ou spécialisation mémorise sa propre hauteur."
L["Wand Height"] = "Hauteur (baguette)"
L["Height of the swing bar in pixels for wand users (Mage, Priest, Warlock)."] = "Hauteur de la barre de coups en pixels pour les utilisateurs de baguette (mage, prêtre, démoniste)."
L["Dual-Wield Height"] = "Hauteur (deux armes)"
L["Height of each bar when dual-wielding (MH and OH bars shown separately)."] = "Hauteur de chaque barre lors du combat à deux armes (barres de main droite et de main gauche affichées séparément)."
L["Dual-Wield Spacing"] = "Espacement (deux armes)"
L["Gap in pixels between the main-hand and off-hand bars."] = "Écart en pixels entre les barres de la main droite et de la main gauche."
L["Show a glowing spark at the fill edge of the bar."] = "Affiche une étincelle lumineuse au bord de remplissage de la barre."
L["Hide Delay"] = "Délai de masquage"
L["Seconds to wait after the last swing before auto-hiding the bar."] = "Secondes à attendre après le dernier coup avant de masquer automatiquement la barre."
L["The fill color of the swing bar. Disabled when class-specific coloring overrides the entire bar."] = "La couleur de remplissage de la barre de coups. Désactivée lorsque la coloration propre à la classe remplace toute la barre."
L["Timer Text"] = "Texte du minuteur"
L["Show Timer Text"] = "Afficher le texte du minuteur"
L["Show a countdown timer on the bar."] = "Affiche un minuteur à rebours sur la barre."
L["Font size for the timer text."] = "Taille de police du texte du minuteur."
L["Text outline style for the swing bar."] = "Style de contour du texte pour la barre de coups."
L["Class Options"] = "Options de classe"
L["Enable Shot Zones"] = "Activer les zones de tir"
L["Color the bar by auto-shot timing:\n\n|cffffffffGreen|r — Safe to cast anything and move freely.\n|cffffffffYellow|r — Steady Shot would clip, but instants and movement are safe.\n|cffffffffRed|r — Don't move or cast Multi-Shot (auto-shot animation playing)."] = "Colore la barre selon le minutage du tir automatique :\n\n|cffffffffVert|r — Vous pouvez tout lancer et vous déplacer librement en toute sécurité.\n|cffffffffJaune|r — Tir assuré tronquerait, mais les sorts instantanés et le déplacement sont sûrs.\n|cffffffffRouge|r — Ne vous déplacez pas et ne lancez pas Tir multiple (animation de tir automatique en cours)."
L["Safe Zone (Green)"] = "Zone sûre (vert)"
L["Bar color when it's safe to cast and move."] = "Couleur de la barre lorsqu'il est sûr de lancer et de se déplacer."
L["Steady Zone (Yellow)"] = "Zone Tir assuré (jaune)"
L["Bar color when Steady Shot would clip, but instant shots and movement are still safe."] = "Couleur de la barre lorsque Tir assuré tronquerait, mais que les tirs instantanés et le déplacement restent sûrs."
L["Stop Zone (Red)"] = "Zone d'arrêt (rouge)"
L["Bar color when moving would cancel your auto-shot and Multi-Shot would clip."] = "Couleur de la barre lorsque se déplacer annulerait votre tir automatique et que Tir multiple tronquerait."
L["Enable Twist Window"] = "Activer la fenêtre d'alternance"
L["Highlight the last ~0.4 seconds before your melee swing with a different color — your cue to swap seals for seal twisting."] = "Met en évidence les ~0,4 dernières secondes avant votre coup de corps à corps avec une couleur différente — votre signal pour changer de sceau lors de l'alternance de sceaux."
L["Twist Window Color"] = "Couleur de la fenêtre d'alternance"
L["Bar color during the seal twist window."] = "Couleur de la barre pendant la fenêtre d'alternance de sceaux."
L["Zone Opacity"] = "Opacité des zones"
L["Opacity of the background zone indicators that preview upcoming color changes on the bar."] = "Opacité des indicateurs de zone en arrière-plan qui prévisualisent les changements de couleur à venir sur la barre."
L["Melee Weaving"] = "Imbrication corps à corps"
L["Show both ranged and melee swing bars simultaneously. For advanced hunters who weave melee attacks (e.g., Raptor Strike) between auto-shots."] = "Affiche simultanément les barres de coups à distance et au corps à corps. Pour les chasseurs avancés qui imbriquent des attaques de corps à corps (p. ex. Attaque du raptor) entre les tirs automatiques."
L["Enable Sync Colors"] = "Activer les couleurs de synchronisation"
L["Sync Threshold"] = "Seuil de synchronisation"
L["Spell Config"] = "Configuration des sorts"
L["Spells"] = "Sorts"
L["Click the button below to open the spell configuration window — enable/disable spells, reorder them, and drag between rows."] = "Cliquez sur le bouton ci-dessous pour ouvrir la fenêtre de configuration des sorts — activez/désactivez les sorts, réorganisez-les et déplacez-les entre les rangées."
L["Open Spell Configuration"] = "Ouvrir la configuration des sorts"
L["Opens the spell configuration window where you can enable/disable spells, reorder them, and move them between rows using drag-and-drop."] = "Ouvre la fenêtre de configuration des sorts où vous pouvez activer/désactiver les sorts, les réorganiser et les déplacer entre les rangées par glisser-déposer."
L["Consumables"] = "Consommables"
L["Track combat consumables on your HUD — potions, runes, and other items you use mid-fight. Each icon shows the item cooldown, buff duration, and bag count. For long-duration pre-pull buffs (elixirs, flasks, food), use a consumable-tracking addon like NovaConsumesHelper."] = "Suivez les consommables de combat sur votre ATH — potions, runes et autres objets que vous utilisez en plein combat. Chaque icône affiche le temps de recharge de l'objet, la durée de l'amélioration et le nombre dans le sac. Pour les améliorations de longue durée d'avant-pull (élixirs, flacons, nourriture), utilisez un addon de suivi de consommables comme NovaConsumesHelper."
L["Spec not yet detected"] = "Spécialisation pas encore détectée"
L["Add Consumables"] = "Ajouter des consommables"
L["Add by Item ID"] = "Ajouter par ID d'objet"
L["Enter an item ID to track any consumable not listed above. You can find item IDs on Wowhead (the number in the URL) or with the idTip addon."] = "Saisissez un ID d'objet pour suivre tout consommable non listé ci-dessus. Vous pouvez trouver les ID d'objets sur Wowhead (le nombre dans l'URL) ou avec l'addon idTip."
L["Invalid input — enter a numeric item ID."] = "Saisie invalide — saisissez un ID d'objet numérique."
L["Item "] = "Objet "
L["Added:"] = "Ajouté :"
L["Tracked Consumables"] = "Consommables suivis"
L["Sounds"] = "Sons"
L["Play a sound when an ability becomes ready — when it comes off cooldown, becomes usable, or meets resource requirements. Set a default sound for all abilities, or override individual spells below.\n\nSound plays for all rows regardless of the Ready Glow row filter. Other settings still apply: combat-only, pre-trigger time, and once vs. re-trigger mode."] = "Joue un son lorsqu'une capacité devient prête — lorsqu'elle sort de temps de recharge, devient utilisable ou atteint les exigences de ressource. Définissez un son par défaut pour toutes les capacités, ou remplacez les sorts individuels ci-dessous.\n\nLe son est joué pour toutes les rangées, indépendamment du filtre de rangées de la Lueur de disponibilité. Les autres réglages s'appliquent toujours : combat uniquement, délai de pré-déclenchement et mode unique ou redéclenchement."
L["Support"] = "Support"
L["Join the "] = "Rejoignez le "
L["Veev Addons Discord"] = "Discord Veev Addons"
L["Discord URL"] = "URL Discord"
L["Press Ctrl+C to copy the URL."] = "Appuyez sur Ctrl+C pour copier l'URL."
L["VeevHUD is built with a $200/mo Claude subscription, late-night coding sessions, and unhealthy amounts of caffeine. I code for the love of the game, not for profit. Donations to help offset the costs are appreciated but never expected!"] = "VeevHUD est conçu avec un abonnement Claude à 200 $/mois, des sessions de code nocturnes et des quantités malsaines de caféine. Je code par amour du jeu, pas pour le profit. Les dons pour aider à compenser les coûts sont appréciés mais jamais attendus !"
L["Donate URL"] = "URL de don"
L["Cooldown Pulse"] = "Pulsation de fin de recharge"
L["Flashes a large icon in the center of the screen when a tracked ability comes off cooldown. A prominent visual cue that complements the ready glow on ability icons."] = "Fait clignoter une grande icône au centre de l'écran lorsqu'une capacité suivie sort de temps de recharge. Un repère visuel bien visible qui complète la lueur de disponibilité sur les icônes de capacités."
L["Enable Cooldown Pulse"] = "Activer la pulsation de fin de recharge"
L["Master toggle for the cooldown pulse effect. When enabled, a large icon briefly flashes on screen each time a tracked ability finishes its cooldown."] = "Bascule principale pour l'effet de pulsation de fin de recharge. Lorsqu'elle est activée, une grande icône clignote brièvement à l'écran chaque fois qu'une capacité suivie termine son temps de recharge."
L["How large the flashing icon appears on screen, in pixels."] = "La taille de l'icône clignotante à l'écran, en pixels."
L["Peak opacity of the icon during the flash. Lower values create a more subtle, ghostly effect."] = "Opacité maximale de l'icône pendant le clignotement. Les valeurs plus faibles créent un effet plus subtil et fantomatique."
L["X Offset"] = "Décalage X"
L["Horizontal offset from the center of your screen. Negative values move left, positive values move right."] = "Décalage horizontal par rapport au centre de votre écran. Les valeurs négatives déplacent vers la gauche, les valeurs positives vers la droite."
L["Y Offset"] = "Décalage Y"
L["Vertical offset from the center of your screen. Negative values move down, positive values move up."] = "Décalage vertical par rapport au centre de votre écran. Les valeurs négatives déplacent vers le bas, les valeurs positives vers le haut."
L["Filtering"] = "Filtrage"
L["Which ability rows trigger the cooldown pulse. Primary Row is your core rotation — the most impactful notifications. Add Secondary to include throughput cooldowns too."] = "Les rangées de capacités qui déclenchent la pulsation de fin de recharge. La rangée principale est votre rotation principale — les notifications les plus importantes. Ajoutez Secondaire pour inclure aussi les temps de recharge de puissance."
L["Only In Combat"] = "En combat uniquement"
L["Only show cooldown pulses while you are in combat."] = "N'affiche les pulsations de fin de recharge que lorsque vous êtes en combat."
L["Ignore Cooldowns Below"] = "Ignorer les temps de recharge inférieurs à"
L["Skip pulses for abilities with cooldowns shorter than this. Useful for filtering out short-cooldown rotational spells. Set to 0 to include everything."] = "Ignore les pulsations pour les capacités dont le temps de recharge est inférieur à cette valeur. Utile pour filtrer les sorts de rotation à court temps de recharge. Réglez sur 0 pour tout inclure."
L["Fade In Effect"] = "Effet d'apparition en fondu"
L["Size effect while the icon fades in. Grow: starts small, grows to normal. Shrink: starts big, shrinks to normal. None: no size change."] = "Effet de taille pendant l'apparition de l'icône en fondu. Agrandir : commence petit, grandit jusqu'à la normale. Rétrécir : commence grand, rétrécit jusqu'à la normale. Aucun : aucun changement de taille."
L["Grow"] = "Agrandir"
L["Shrink"] = "Rétrécir"
L["Fade Out Effect"] = "Effet de disparition en fondu"
L["Size effect while the icon fades out. Grow: grows from normal to big. Shrink: shrinks from normal to small. None: no size change."] = "Effet de taille pendant la disparition de l'icône en fondu. Agrandir : grandit de la normale jusqu'à grand. Rétrécir : rétrécit de la normale jusqu'à petit. Aucun : aucun changement de taille."
L["Fade In"] = "Apparition en fondu"
L["How long the icon takes to fade in, in seconds."] = "Le temps que met l'icône à apparaître en fondu, en secondes."
L["Hold Time"] = "Temps de maintien"
L["How long the icon stays at peak opacity before fading out. Set to 0 for a quick flash, or increase for a longer notification."] = "La durée pendant laquelle l'icône reste à l'opacité maximale avant de disparaître en fondu. Réglez sur 0 pour un clignotement rapide, ou augmentez pour une notification plus longue."
L["Fade Out"] = "Disparition en fondu"
L["How long the icon takes to fade out, in seconds."] = "Le temps que met l'icône à disparaître en fondu, en secondes."
L["Early Trigger"] = "Déclenchement anticipé"
L["Fire the pulse this many seconds before the cooldown finishes. Gives you a head start on reacting. Set to 0 to pulse at the exact moment the ability becomes ready."] = "Déclenche la pulsation ce nombre de secondes avant la fin du temps de recharge. Vous donne une longueur d'avance pour réagir. Réglez sur 0 pour pulser au moment exact où la capacité devient prête."
L["Test Pulse"] = "Tester la pulsation"
L["Plays a test pulse so you can preview your current settings."] = "Joue une pulsation de test afin que vous puissiez prévisualiser vos réglages actuels."
L["No consumables added yet. Select one from the dropdowns above."] = "Aucun consommable ajouté pour l'instant. Sélectionnez-en un dans les menus déroulants ci-dessus."
L["Remove"] = "Retirer"
L["Remove this consumable from tracking."] = "Retire ce consommable du suivi."
L["Any"] = "Tout"
L["Own"] = "Soi"
L["Others"] = "Autres"
L["Icon"] = "Icône"
L["Show this aura as a compact icon in the icon row, or as a status bar with name and timer in the bar stack below the icons."] = "Affiche cette aura sous forme d'icône compacte dans la rangée d'icônes, ou sous forme de barre d'état avec nom et minuteur dans la pile de barres sous les icônes."
L["Fill color for this aura's timer bar (Bar display mode only). Defaults to a vibrant color sampled from the spell's icon — change it here to override."] = "Couleur de remplissage de la barre de minuteur de cette aura (mode d'affichage Barre uniquement). Par défaut, une couleur vive échantillonnée depuis l'icône du sort — changez-la ici pour la remplacer."
L["Toggle which class procs are tracked. Enabled procs appear as icons in the Aura Tracker when active."] = "Activez ou désactivez les procs de classe suivis. Les procs activés apparaissent sous forme d'icônes dans le Suivi d'auras lorsqu'ils sont actifs."
L["Show this aura in the tracker."] = "Affiche cette aura dans le suivi."
L["Show the glowing border and backdrop halo when this aura is active. Disable for auras you want to track quietly without the glow drawing your eye."] = "Affiche la bordure lumineuse et le halo de fond lorsque cette aura est active. Désactivez pour les auras que vous voulez suivre discrètement sans que la lueur n'attire votre regard."
L["Sound to play when this aura activates. 'None' uses the global default from the Sound section above."] = "Son à jouer lorsque cette aura s'active. « Aucun » utilise le réglage global par défaut de la section Son ci-dessus."
L["Refresh"] = "Renouvellement"
L["Also play the sound when this aura refreshes (is reapplied while already active)."] = "Joue aussi le son lorsque cette aura se renouvelle (est réappliquée alors qu'elle est déjà active)."
L["Settings"] = "Réglages"
L["Class Procs"] = "Procs de classe"
L["External Buffs"] = "Améliorations externes"
L["Custom Auras"] = "Auras personnalisées"
L["Toggle which external buffs are tracked (from other players, consumables, or PvP powerups). These appear as icons in the Aura Tracker when active on you."] = "Activez ou désactivez les améliorations externes suivies (provenant d'autres joueurs, de consommables ou de bonus JcJ). Elles apparaissent sous forme d'icônes dans le Suivi d'auras lorsqu'elles sont actives sur vous."
L["Track %s (ID: %s)"] = "Suivre %s (ID : %s)"
L["Show the glowing border and backdrop halo when this aura is active."] = "Affiche la bordure lumineuse et le halo de fond lorsque cette aura est active."
L["Sound to play when this aura activates. 'None' uses the global default."] = "Son à jouer lorsque cette aura s'active. « Aucun » utilise le réglage global par défaut."
L["Also play the sound when this aura refreshes."] = "Joue aussi le son lorsque cette aura se renouvelle."
L["Add custom auras to track by spell ID or spell name. These work like procs — the icon appears when the buff is active on you."] = "Ajoutez des auras personnalisées à suivre par ID de sort ou nom de sort. Elles fonctionnent comme des procs — l'icône apparaît lorsque l'amélioration est active sur vous."
L["Spell ID or Name"] = "ID ou nom de sort"
L["Enter a numeric spell ID or exact spell name and press Enter to add.\n\nYou can find spell IDs on Wowhead (the number at the end of the spell URL), or install the idTip addon to see spell IDs directly in tooltips."] = "Saisissez un ID de sort numérique ou un nom de sort exact, puis appuyez sur Entrée pour ajouter.\n\nVous pouvez trouver les ID de sorts sur Wowhead (le nombre à la fin de l'URL du sort), ou installer l'addon idTip pour voir les ID de sorts directement dans les info-bulles."
L["(icon shows when buff is active)"] = "(l'icône s'affiche quand l'amélioration est active)"
L["(by name — icon shows when buff is active)"] = "(par nom — l'icône s'affiche quand l'amélioration est active)"
L["Current Custom Auras"] = "Auras personnalisées actuelles"
L["Recently Seen Buffs"] = "Améliorations vues récemment"
L["No custom auras added yet."] = "Aucune aura personnalisée ajoutée pour l'instant."
L["(ID: "] = "(ID : "
L["Del"] = "Suppr"
L["Remove this custom aura."] = "Retire cette aura personnalisée."
L["No recent buffs recorded yet. Play for a bit and reopen this tab."] = "Aucune amélioration récente enregistrée pour l'instant. Jouez un moment et rouvrez cet onglet."
L["All recent buffs are already tracked."] = "Toutes les améliorations récentes sont déjà suivies."
L["Add"] = "Ajouter"
L["In Combat"] = "En combat"
L["Out of Combat"] = "Hors combat"
L["Player"] = "Joueur"
L["Party"] = "Groupe"
L["Raid"] = "Raid"
L["Enable or disable this buff reminder."] = "Active ou désactive ce rappel d'amélioration."
L["Time Threshold"] = "Seuil de temps"
L["Show the reminder when the buff has less than this many seconds remaining. Set to 0 to only remind when the buff is completely missing."] = "Affiche le rappel lorsqu'il reste moins que ce nombre de secondes à l'amélioration. Réglez sur 0 pour ne rappeler que lorsque l'amélioration est complètement absente."
L["Combat"] = "Combat"
L["When to show this reminder based on combat state."] = "Quand afficher ce rappel selon l'état de combat."
L["Track"] = "Suivre"
L["Who to check for this buff.\n\n|cffffffffPlayer|r: Only check yourself.\n|cffffffffParty|r: Check all party members (or only yourself if solo).\n|cffffffffRaid|r: Check all raid members (downsizes to party if not in a raid)."] = "Qui vérifier pour cette amélioration.\n\n|cffffffffJoueur|r : vous vérifie uniquement.\n|cffffffffGroupe|r : vérifie tous les membres du groupe (ou seulement vous si vous êtes en solo).\n|cffffffffRaid|r : vérifie tous les membres du raid (se réduit au groupe si vous n'êtes pas en raid)."
L["Sound to play when this buff reminder appears. 'None' uses the global default from the General tab."] = "Son à jouer lorsque ce rappel d'amélioration apparaît. « Aucun » utilise le réglage global par défaut de l'onglet Général."
L["Min Stacks"] = "Cumuls min"
L["Show the reminder when stacks fall below this number. Set to 0 to disable stack checking. This is an OR condition with the time threshold."] = "Affiche le rappel lorsque les cumuls tombent en dessous de ce nombre. Réglez sur 0 pour désactiver la vérification des cumuls. C'est une condition OU avec le seuil de temps."
L["Priority"] = "Priorité"
L["Which spell to remind first when no buff from this group is active."] = "Quel sort rappeler en premier lorsqu'aucune amélioration de ce groupe n'est active."
L["Main Hand"] = "Main droite"
L["Show a reminder when your main hand weapon is missing an enchant. Disable this if you prefer to benefit from a Shaman's Windfury Totem instead."] = "Affiche un rappel lorsqu'il manque un enchantement à l'arme de votre main droite. Désactivez ceci si vous préférez bénéficier du Totem furie-des-vents d'un chaman à la place."
L["Off Hand"] = "Main gauche"
L["Show a reminder when your off hand weapon is missing an enchant."] = "Affiche un rappel lorsqu'il manque un enchantement à l'arme de votre main gauche."
L["Configure which buff reminders are active. Settings on this tab are per-spec — switching specs loads that spec's configuration."] = "Configurez les rappels d'améliorations actifs. Les réglages de cet onglet sont par spécialisation — changer de spécialisation charge la configuration de cette spécialisation."
L["Show Only Known Spells"] = "Afficher uniquement les sorts connus"
L["Only shows spells you currently know. Disable to see all class buff spells, including ones you haven't learned yet."] = "N'affiche que les sorts que vous connaissez actuellement. Désactivez pour voir tous les sorts d'amélioration de classe, y compris ceux que vous n'avez pas encore appris."
L["Buff Reminders"] = "Rappels d'améliorations"
L["Buff Reminders show a large, semi-transparent icon when a long-duration buff you should maintain is missing or about to expire. They are separate from the main HUD icons and only appear when action is needed.\n\nReminders automatically check that you know the spell and have the resources to cast it. Use the Spells tab to configure individual reminders."] = "Les rappels d'améliorations affichent une grande icône semi-transparente lorsqu'une amélioration de longue durée que vous devriez maintenir est absente ou sur le point d'expirer. Ils sont distincts des icônes principales de l'ATH et n'apparaissent que lorsqu'une action est nécessaire.\n\nLes rappels vérifient automatiquement que vous connaissez le sort et que vous disposez des ressources pour le lancer. Utilisez l'onglet Sorts pour configurer les rappels individuels."
L["Enable Buff Reminders"] = "Activer les rappels d'améliorations"
L["Master toggle for the Buff Reminders feature. When disabled, no buff reminder icons will be shown."] = "Bascule principale pour la fonction Rappels d'améliorations. Lorsqu'elle est désactivée, aucune icône de rappel d'amélioration ne sera affichée."
L["The size of buff reminder icons in pixels."] = "La taille des icônes de rappel d'amélioration en pixels."
L["The horizontal gap between buff reminder icons."] = "L'écart horizontal entre les icônes de rappel d'amélioration."
L["Icon Opacity"] = "Opacité des icônes"
L["The opacity of the buff reminder icons."] = "L'opacité des icônes de rappel d'amélioration."
L["Text outline style for buff reminder text."] = "Style de contour du texte pour les rappels d'améliorations."
L["Pulse Animation"] = "Animation de pulsation"
L["Reminder icons gently pulse to draw attention."] = "Les icônes de rappel pulsent doucement pour attirer l'attention."
L["Respect Resource Cost"] = "Respecter le coût en ressource"
L["Only show buff reminders when you have enough resources (mana, rage, energy) to cast the spell. Uncheck to always show reminders for missing buffs regardless of your current resource level."] = "N'affiche les rappels d'améliorations que lorsque vous avez assez de ressources (mana, rage, énergie) pour lancer le sort. Décochez pour toujours afficher les rappels d'améliorations absentes, quel que soit votre niveau de ressource actuel."
L["Show While Resting"] = "Afficher au repos"
L["Show buff reminders while in inns and cities."] = "Affiche les rappels d'améliorations dans les auberges et les villes."
L["Show While Mounted"] = "Afficher à cheval"
L["Show buff reminders while mounted."] = "Affiche les rappels d'améliorations lorsque vous êtes à cheval."
L["When buff reminders appear or disappear, the remaining icons smoothly slide to re-center instead of snapping instantly. Disable for instant repositioning."] = "Lorsque les rappels d'améliorations apparaissent ou disparaissent, les icônes restantes glissent en douceur pour se recentrer au lieu de se replacer instantanément. Désactivez pour un repositionnement instantané."
L["Sound to play when a buff reminder first appears. Individual spells can override this in the Spells tab."] = "Son à jouer lorsqu'un rappel d'amélioration apparaît pour la première fois. Les sorts individuels peuvent remplacer ce réglage dans l'onglet Sorts."
L["Position"] = "Position"
L["Horizontal offset of buff reminder icons relative to the HUD. The range adjusts to your screen resolution."] = "Décalage horizontal des icônes de rappel d'amélioration par rapport à l'ATH. La plage s'ajuste à la résolution de votre écran."
L["Vertical offset of buff reminder icons relative to the HUD. The range adjusts to your screen resolution."] = "Décalage vertical des icônes de rappel d'amélioration par rapport à l'ATH. La plage s'ajuste à la résolution de votre écran."
L["Toggle a sample buff reminder icon so you can see your settings in action."] = "Affiche un exemple d'icône de rappel d'amélioration afin que vous puissiez voir vos réglages en action."
L["Default"] = "Par défaut"
L["Sound to play when the ready glow activates on any ability. Per-spell overrides below take priority."] = "Son à jouer lorsque la lueur de disponibilité s'active sur une capacité. Les remplacements par sort ci-dessous ont la priorité."
L["Primary"] = "Principale"
L["Secondary"] = "Secondaire"
L["Utility"] = "Utilitaire"
L["Auxiliary"] = "Auxiliaire"
